class Solution {
    int[][] DIRS = new int[][] { { -1, 0 }, { 1, 0 }, { 0, 1 }, { 0, -1 } };
    public boolean exist(char[][] board, String word) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                if (dfs(board, i, j, 0, word)) {
                    return true;
                }
            }
        }
        return false;
    }
    public boolean dfs(char[][] board, int x, int y, int k, String word) {
        if (x < 0 || x >= board.length || y < 0 || y >= board[0].length) {
            return false;
        }
        if (board[x][y] != word.charAt(k)) {
            return false;
        }
        if (k == word.length() - 1)
            return true;
        char Temp = board[x][y];
        board[x][y] = '0';
        for (int[] dir : DIRS) {
            if(dfs(board, x + dir[0], y + dir[1], k + 1, word)){
                return true;
            }
        }
        board[x][y] = Temp;
        return false;
    }
}
